import type { DesiredFile, EmitInput } from "./context.js";

const WORKFLOW = (installStep: string) => `name: keel-verify

# Generated by keel — edit autonomy.ci in harness.yaml, then run keel apply.
# Gates every PR on: lockfile drift (generated files edited without apply)
# and the full verify gate (boundaries + style + project verify commands).
on:
  push:
    branches: [main]
  pull_request:

jobs:
  keel:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - run: corepack enable || true
${installStep}      - run: node .keel/check-drift.mjs
      - run: node .keel/verify.mjs
`;

/** CI workflow emitter — currently GitHub Actions only (autonomy.ci: github). */
export function emitCi(input: EmitInput): { files: DesiredFile[]; warnings: string[] } {
  const { spec, fp } = input;
  if (spec.autonomy.ci !== "github") return { files: [], warnings: [] };

  // JS repos need deps installed before the verify gate runs; other stacks get
  // the drift check only (verify still runs — its commands decide their own needs).
  const hasPkg = (fp?.scripts ?? []).length > 0 || spec.stack.language === "typescript" || spec.stack.language === "javascript";
  const installStep = hasPkg ? `      - run: ${spec.stack.package_manager} install\n` : "";

  return {
    files: [
      {
        path: ".github/workflows/keel-verify.yml",
        content: WORKFLOW(installStep),
        origin: "keel/ci",
      },
    ],
    warnings: [],
  };
}
